args.command:
node --input-type=module -e "
import { createClient } from '@clickhouse/client';
const client = createClient({ url: process.env.CLICKHOUSE_URL });
const query = \"SELECT sum(amount) FROM analytics.events WHERE region = 'us-west' AND event_ts >= '2026-01-01'\";
for (let i = 0; i < 10; i++) {
  const start = Date.now();
  await client.query({ query, format: 'JSONEachRow' });
  const elapsed = Date.now() - start;
  console.log('elapsedMs', elapsed);
}
await client.close();
"

